#include <iostream>
#include <string>

class Resource {
public:
    std::string name;
    Resource() : name("default") {}
    Resource(std::string n) : name(std::move(n)) {}
    ~Resource() {
        // Destructor prints notification when freed
    }
};

int main() {
    int capacity = 2;
    Resource* arr = new Resource[capacity];
    arr[0] = Resource("ResA");
    arr[1] = Resource("ResB");

    // Simulate ensureCapacity doubling
    int newCapacity = capacity * 2;
    Resource* newArr = new Resource[newCapacity];
    for (int i = 0; i < capacity; ++i) {
        newArr[i] = arr[i];
    }

    // Correct deallocation requires delete[]
    delete [] arr;
    arr = newArr;

    std::cout << "Expanded capacity to " << newCapacity << ", arr[0]=" << arr[0].name << std::endl;

    delete [] arr;
    return 0;
}

#include <iostream>
#include <vector>
#include <string>

int main() {
    // 1. Integer vector push_back and size
    std::vector<int> intVector;
    for (int i = 1; i <= 5; ++i) {
        intVector.push_back(i * 10);
    }

    std::cout << "intVector elements:";
    for (std::size_t i = 0; i < intVector.size(); ++i) {
        std::cout << " " << intVector[i];
    }
    std::cout << "\n";

    // 2. String vector, swap, and bounds-checked at()
    std::vector<std::string> cities;
    cities.push_back("Dallas");
    cities.push_back("Houston");
    cities.push_back("Austin");
    cities.pop_back(); // removes "Austin"

    std::vector<std::string> v2;
    v2.swap(cities);
    v2[0] = "Atlanta";

    std::cout << "v2 elements via at():";
    for (std::size_t i = 0; i < v2.size(); ++i) {
        std::cout << " " << v2.at(i);
    }
    std::cout << "\n";

    // 3. 2D vector (matrix)
    std::vector<std::vector<int>> matrix(2, std::vector<int>(3, 1));
    matrix[0][1] = 5;
    int total = 0;
    for (const auto& row : matrix) {
        for (int val : row) {
            total += val;
        }
    }
    std::cout << "Matrix sum: " << total << std::endl;

    return 0;
}
